mapper.update:
UPDATE campaign_delivery SET status = #{toStatus}, last_error = NULL, last_error_code = NULL, reconciliation_required_at = NULL WHERE workspace_id = #{workspaceId} AND id = #{id} AND status IN
#{from}
AND (status != 'failed' OR reconciliation_required_at IS NOT NULL)

mapper.select:
SELECT COUNT(*) FROM campaign_delivery d
JOIN campaign_send s ON s.workspace_id = d.workspace_id AND s.id = d.send_id
WHERE d.workspace_id = #{workspaceId}
  AND d.person_id = #{personId}
  AND s.channel = #{channel}
  AND d.send_id != #{sendId}
  AND d.status = 'dispatched'
  AND d.updated_at >= #{since}

SELECT EXISTS (
  SELECT 1 FROM campaign_delivery_event
  WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId} AND event_type = #{eventType}
)
